script:
// Purchase Order: copy Company > Default Receipt Warehouse into Set Target Warehouse on new orders
(function () {

frappe.ui.form.on('Purchase Order', {
    onload: function (frm) {
        schedule_company_warehouse(frm);
    },
    refresh: function (frm) {
        schedule_company_warehouse(frm);
    },
    company: function (frm) {
        frm.__po_wh_done = false;
        schedule_company_warehouse(frm);
    }
});

// run a moment later so other scripts and ERPNext have finished loading the form
function schedule_company_warehouse(frm) {
    if (!frm.is_new() || frm.__po_wh_done || frm.__po_wh_timer) return;
    frm.__po_wh_timer = setTimeout(function () {
        frm.__po_wh_timer = null;
        apply_company_warehouse(frm);
    }, 600);
}

function apply_company_warehouse(frm) {
    if (!frm.is_new() || frm.__po_wh_done || frm.doc.set_warehouse) return;

    var company = frm.doc.company || frappe.defaults.get_user_default('Company');
    if (!company) {
        console.log('PO WAREHOUSE: no company found on this form');
        return;
    }

    frm.__po_wh_done = true;

    frappe.db.get_value('Company', company, 'custom_default_receipt_warehouse').then(function (r) {
        var wh = r.message && r.message.custom_default_receipt_warehouse;
        if (!wh) {
            frappe.show_alert({
                message: 'Default Receipt Warehouse is empty on company ' + company,
                indicator: 'orange'
            }, 8);
            return;
        }
        if (!frm.doc.set_warehouse) {
            frm.set_value('set_warehouse', wh);
            frappe.show_alert({ message: 'Target warehouse set to ' + wh, indicator: 'green' }, 5);
        }
    }, function () {
        frappe.show_alert({
            message: 'Could not read Default Receipt Warehouse from the Company',
            indicator: 'red'
        }, 8);
    });
}

})();
// END OF SCRIPT

frappe.ui.form.on("Stock Entry", {
    refresh(frm) {
        // Show a message for submitted Stock Entries.
        if (frm.doc.docstatus === 1) {
            frm.dashboard.set_headline(
                __("Item storage locations are updated by the server.")
            );
        }
    },

    validate(frm) {
        // Validate storage-location rows before saving or submitting.
        const rows = frm.doc.custom_storage_location || [];

        for (const row of rows) {
            if (row.item && !row.warehouse) {
                frappe.throw(
                    __("Please select a Warehouse for Item {0}.", [
                        row.item
                    ])
                );
            }
        }
    }
});

// Purchase Order: fill custom_full_items (PO Full Item) from the rows in the items table
var TARGET_TABLE = 'custom_full_items';
var SOURCE_TABLE = 'items';
var BOX_DEBUG = false;

frappe.ui.form.on('Purchase Order Item', {
    item_code: function (frm, cdt, cdn) {
        if (is_source_row(cdt, cdn)) queue_rebuild(frm);
    },
    qty: function (frm, cdt, cdn) {
        if (is_source_row(cdt, cdn)) queue_rebuild(frm);
    }
});

frappe.ui.form.on('Purchase Order', {
    items_remove: function (frm) {
        queue_rebuild(frm);
    }
});

function step(msg, color) {
    console.log('BOX SCRIPT: ' + msg);
    if (BOX_DEBUG || color === 'red' || color === 'orange') {
        frappe.show_alert({ message: msg, indicator: color || 'blue' }, 8);
    }
}

function wait(ms) {
    return new Promise(function (resolve) { setTimeout(resolve, ms); });
}

function load_doctype(dt) {
    return new Promise(function (resolve) {
        frappe.model.with_doctype(dt, function () { resolve(); });
    });
}

function is_source_row(cdt, cdn) {
    var row = locals[cdt] && locals[cdt][cdn];
    return !!row && row.parentfield === SOURCE_TABLE;
}

function queue_rebuild(frm) {
    clearTimeout(frm.__box_timer);
    frm.__box_timer = setTimeout(function () {
        build_full_items(frm);
    }, 1200);
}

function get_is_box(item) {
    var meta = frappe.get_meta('Item');
    if (!meta) return null;
    var f = meta.fields.find(function (x) {
        var label = (x.label || '').toLowerCase().replace(/\s+/g, ' ').trim();
        return x.fieldtype === 'Check' &&
            (label === 'is box item' || (x.fieldname || '').indexOf('is_box') > -1);
    });
    if (!f) return null;
    return cint(item[f.fieldname]) === 1;
}

function find_box_rows(item) {
    var meta = frappe.get_meta('Item');
    var tables = meta ? meta.fields.filter(function (f) {
        return f.fieldtype === 'Table';
    }) : [];

    var f = tables.find(function (x) { return x.options === 'Box Items'; });
    if (f && (item[f.fieldname] || []).length) return item[f.fieldname];

    f = tables.find(function (x) {
        return (x.fieldname || '').indexOf('box') > -1 ||
            (x.label || '').toLowerCase().indexOf('box') > -1;
    });
    if (f && (item[f.fieldname] || []).length) return item[f.fieldname];

    var keys = Object.keys(item);
    for (var i = 0; i < keys.length; i++) {
        var v = item[keys[i]];
        if (Array.isArray(v) && v.length && v[0] && v[0].doctype === 'Box Items') return v;
    }
    return [];
}

// finds the real fieldnames of the Full Items child table
function get_full_fields() {
    var df = frappe.meta.get_docfield('Purchase Order', TARGET_TABLE);
    if (!df) return Promise.resolve({});
    return load_doctype(df.options).then(function () {
        var meta = frappe.get_meta(df.options);
        var fields = meta ? meta.fields : [];

        var has = function (x, words) {
            var s = ((x.fieldname || '') + ' ' + (x.label || '')).toLowerCase();
            return words.some(function (w) { return s.indexOf(w) > -1; });
        };
        var isItemLink = function (x) { return x.fieldtype === 'Link' && x.options === 'Item'; };

        var box = fields.find(function (x) { return isItemLink(x) && has(x, ['box']); });
        var item = fields.find(function (x) { return isItemLink(x) && x !== box; }) ||
                   fields.find(function (x) { return ['item', 'item_code'].indexOf(x.fieldname) > -1; });
        var name = fields.find(function (x) { return x.fieldtype === 'Data' && has(x, ['name']); });
        var qty = fields.find(function (x) { return ['Float', 'Int'].indexOf(x.fieldtype) > -1 && has(x, ['qty', 'quantity']); }) ||
                  fields.find(function (x) { return ['Float', 'Int'].indexOf(x.fieldtype) > -1; });
        var uom = fields.find(function (x) { return x.fieldtype === 'Link' && x.options === 'UOM'; });

        return {
            item: item && item.fieldname,
            name: name && name.fieldname,
            qty: qty && qty.fieldname,
            uom: uom && uom.fieldname,
            box: box && box.fieldname,
            all: fields.map(function (x) { return x.fieldname; }).join(', ')
        };
    });
}

function get_item(cache, code) {
    if (cache[code]) return Promise.resolve(cache[code]);
    return Promise.resolve(frappe.call({
        method: 'frappe.client.get',
        args: { doctype: 'Item', name: code }
    })).then(function (r) {
        cache[code] = r.message;
        return r.message;
    });
}

function get_info(cache, code) {
    if (cache[code]) return Promise.resolve(cache[code]);
    return Promise.resolve(
        frappe.db.get_value('Item', code, ['item_name', 'stock_uom'])
    ).then(function (r) {
        cache[code] = (r && r.message) || {};
        return cache[code];
    });
}

function add_full_row(frm, f, d) {
    var row = {};
    row[f.item] = d.item_code;
    if (f.name) row[f.name] = d.item_name;
    if (f.qty) row[f.qty] = d.qty;
    if (f.uom) row[f.uom] = d.uom;
    if (f.box && d.source_box) row[f.box] = d.source_box;
    frm.add_child(TARGET_TABLE, row);
}

function set_supplier_if_empty(frm, item) {
    if (frm.doc.supplier) return Promise.resolve();
    var supplier = item.supplier;
    if (!supplier) {
        var si = (item.supplier_items || []).filter(function (d) { return d.supplier; });
        if (si.length) supplier = si[0].supplier;
    }
    if (supplier) return Promise.resolve(frm.set_value('supplier', supplier));
    return Promise.resolve();
}

// add the parts of a box one by one
function add_box_parts(ctx, item, box_rows, src_qty, i) {
    if (i >= box_rows.length) return Promise.resolve();
    var b = box_rows[i];
    var code = b[ctx.linkName] || b.item || b.item_code;
    if (!code) return add_box_parts(ctx, item, box_rows, src_qty, i + 1);
    return get_info(ctx.info_cache, code).then(function (info) {
        add_full_row(ctx.frm, ctx.f, {
            item_code: code,
            item_name: info.item_name,
            qty: flt(b.quantity || b.qty || 1) * src_qty,
            uom: b.uom || info.stock_uom,
            source_box: item.name
        });
        ctx.added++;
        return add_box_parts(ctx, item, box_rows, src_qty, i + 1);
    });
}

// handle one row of the items table
function process_row(ctx, src) {
    var frm = ctx.frm;
    var src_qty = flt(src.qty) || 1;
    return get_item(ctx.item_cache, src.item_code).then(function (item) {
        if (!item) {
            step('Could not read the Item ' + src.item_code, 'red');
            return;
        }
        return set_supplier_if_empty(frm, item).then(function () {
            var box_rows = find_box_rows(item);
            var is_box = get_is_box(item);
            if (is_box === null) is_box = box_rows.length > 0;

            if (is_box && box_rows.length) {
                return add_box_parts(ctx, item, box_rows, src_qty, 0);
            }
            if (is_box) {
                step('Is Box Item is ticked but no Box Items found on ' + (item.item_name || item.name), 'orange');
            }
            return get_info(ctx.info_cache, item.name).then(function (info) {
                add_full_row(frm, ctx.f, {
                    item_code: item.name,
                    item_name: info.item_name,
                    qty: src_qty,
                    uom: src.uom || info.stock_uom
                });
                ctx.added++;
            });
        });
    });
}

function process_rows(ctx, rows, idx) {
    if (idx >= rows.length) return Promise.resolve();
    return process_row(ctx, rows[idx]).then(function () {
        return process_rows(ctx, rows, idx + 1);
    });
}

function build_full_items(frm) {
    if (frm.__loading_box) {
        frm.__box_pending = true;
        return;
    }
    frm.__loading_box = true;
    frm.__box_pending = false;

    var ctx = { frm: frm, f: null, item_cache: {}, info_cache: {}, added: 0, linkName: 'item' };

    load_doctype('Item')
        .then(function () { return load_doctype('Box Items'); })
        .then(function () { return get_full_fields(); })
        .then(function (f) {
            ctx.f = f;
            if (!f.item) {
                step('Full Items table: no Item field found. Fields: ' + (f.all || 'none'), 'red');
                return;
            }

            var source_rows = (frm.doc[SOURCE_TABLE] || []).filter(function (r) { return r.item_code; });

            frm.clear_table(TARGET_TABLE);

            if (!source_rows.length) {
                frm.refresh_field(TARGET_TABLE);
                return;
            }

            var boxMeta = frappe.get_meta('Box Items');
            var linkField = boxMeta ? boxMeta.fields.find(function (x) {
                return x.fieldtype === 'Link' && x.options === 'Item';
            }) : null;
            ctx.linkName = linkField ? linkField.fieldname : 'item';

            return process_rows(ctx, source_rows, 0).then(function () {
                frm.refresh_field(TARGET_TABLE);
                frappe.show_alert({
                    message: 'Full Items updated (' + ctx.added + ' rows)',
                    indicator: 'green'
                });
            });
        })
        .catch(function (e) {
            console.error(e);
            step('FAILED: ' + ((e && e.message) || e), 'red');
        })
        .then(function () { return wait(300); })
        .then(function () {
            frm.__loading_box = false;
            if (frm.__box_pending) {
                frm.__box_pending = false;
                queue_rebuild(frm);
            }
        });
}
// END OF SCRIPT

frappe.ui.form.on("Service Entry", {

    service_id: async function(frm) {

        // Clear existing values
        const fields = [
            "vehicle_number",
            "item",
            "brand",
            "item_group"
        ];

        if (!frm.doc.service_id) {
            for (const field of fields) {
                await frm.set_value(field, "");
            }
            return;
        }

        try {

            // Fetch selected Service Request
            const response = await frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Service Request",
                    name: frm.doc.service_id
                }
            });

            const service = response.message;

            if (!service) {
                frappe.msgprint("Service Request not found.");
                return;
            }

            // Fetch all details from Service Request
            await frm.set_value(
                "vehicle_number",
                service.vehicle_number || ""
            );

            await frm.set_value(
                "item",
                service.item || ""
            );

            await frm.set_value(
                "brand",
                service.brand || ""
            );

            await frm.set_value(
                "item_group",
                service.item_group || ""
            );

            frappe.show_alert({
                message: __("Service Request details fetched successfully"),
                indicator: "green"
            });

        } catch (error) {

            console.error("Service Request Fetch Error:", error);

            frappe.msgprint({
                title: __("Fetch Error"),
                indicator: "red",
                message: __("Unable to fetch Service Request details.")
            });
        }
    }
});

// false = one row per part, quantity copied   (Dio Tyre -> 1 row, qty 2)
// true  = one row per unit, each with qty 1   (Dio Tyre -> 2 rows, qty 1 each)
const ONE_ROW_PER_UNIT = true;

frappe.ui.form.on("Vehicle Tear Down", {
    onload: async function(frm) {
        await load_box_items(frm);
    },

    refresh: async function(frm) {
        await load_box_items(frm);
    },

    item: async function(frm) {
        await load_box_items(frm);
    }
});


async function load_box_items(frm) {

    if (frm.doc.docstatus !== 0 || !frm.doc.item) {
        return;
    }

    // Do not overwrite existing or manually entered recovered parts.
    if ((frm.doc.recovered_parts || []).length > 0) {
        return;
    }

    try {
        const item_doc = await frappe.db.get_doc(
            "Item",
            frm.doc.item
        );

        // Check again after the asynchronous request.
        if (frm.doc.docstatus !== 0 || (frm.doc.recovered_parts || []).length) {
            return;
        }

        const box_items = item_doc.custom_box_items || [];

        if (!box_items.length) {
            console.log("No Box Items found for:", frm.doc.item);
            return;
        }

        box_items.forEach(box => {

            if (!box.item) return;

            // Quantity defined in the Item's "Inside Items" table.
            const qty = flt(box.quantity) > 0 ? flt(box.quantity) : 1;

            if (ONE_ROW_PER_UNIT) {
                // qty 2 -> 2 rows, each with quantity 1.
                for (let i = 0; i < cint(qty); i++) {
                    const row = frm.add_child("recovered_parts");
                    row.item_code = box.item;
                    row.quantity = 1;
                }
            } else {
                // One row with the quantity copied from the Item.
                const row = frm.add_child("recovered_parts");
                row.item_code = box.item;
                row.quantity = qty;
            }

            // Leave disposition blank for operator selection.
        });

        frm.refresh_field("recovered_parts");

        // Synchronize after recovered parts are populated.
        if (typeof window.sync_tear_down_storage === "function") {
            window.sync_tear_down_storage(frm);
        }

        console.log("Box Items loaded successfully:", box_items);

    } catch (error) {

        console.error("Box Items loading failed:", error);

        frappe.msgprint({
            title: __("Box Items Error"),
            indicator: "red",
            message: __("Unable to fetch Box Items from the selected Item.")
        });
    }
}

(function () {

    // --------------------------------------------------
    // CONFIGURATION
    // --------------------------------------------------

    var TABLE = 'custom_storage_location';
    var FLAG = 'custom_is_warehouse_storage';
    var SAME_LOCATION_FLAG = 'custom_same_location';

    var F = {
        item: 'item',
        warehouse: 'warehouse',
        floor: 'floor',
        area: 'area',
        shelf: 'shelf',
        rack: 'rack',
        uom: 'uom',
        qty: 'quantity'
    };

    var LOCATION_FIELDS = [F.warehouse, F.floor, F.area, F.shelf, F.rack];

    var SKIP = [
        'name', 'owner', 'creation', 'modified', 'modified_by',
        'docstatus', 'idx', 'parent', 'parentfield', 'parenttype',
        'doctype', '__islocal', '__unsaved'
    ];

    function is_work_order_entry(frm) {
        return !!frm.doc.work_order;
    }

    // --------------------------------------------------
    // AUTO-FILL TRACKING
    // frm.__auto[key]   = true  -> row was filled by Same Location
    // frm.__backup[key] = {...} -> manual values that the tick overwrote
    // key = item#occurrence (stays stable when rows are rebuilt)
    // --------------------------------------------------

    function ensure_state(frm) {
        if (!frm.__auto) frm.__auto = {};
        if (!frm.__backup) frm.__backup = {};
    }

    function row_key_map(frm) {
        var counts = {};
        var map = {};

        (frm.doc[TABLE] || []).forEach(function (r) {
            var item = r[F.item];
            if (!item) return;
            counts[item] = (counts[item] || 0) + 1;
            map[r.name] = item + '#' + counts[item];
        });

        return map;
    }

    function has_location(row) {
        return LOCATION_FIELDS.some(function (f) { return !!row[f]; });
    }

    // copy source location into row, remember it as auto-filled
    function apply_auto(frm, row, key, source) {

        ensure_state(frm);

        // keep the user's own values so untick can bring them back
        if (!frm.__auto[key] && has_location(row) && !frm.__backup[key]) {
            var backup = {};
            LOCATION_FIELDS.forEach(function (f) { backup[f] = row[f] || ''; });
            frm.__backup[key] = backup;
        }

        LOCATION_FIELDS.forEach(function (f) { row[f] = source[f] || ''; });
        frm.__auto[key] = true;
    }

    // the user typed in this row -> it is manual, never cleared on untick
    function mark_manual(frm, row) {

        ensure_state(frm);

        var key = row_key_map(frm)[row.name];
        if (!key) return;

        delete frm.__auto[key];
        delete frm.__backup[key];
    }

    // --------------------------------------------------
    // STOCK ENTRY EVENTS
    // --------------------------------------------------

    frappe.ui.form.on('Stock Entry', {

        refresh: function (frm) {

            if (is_work_order_entry(frm)) return;

            // Get Items From > Purchase Receipt (Store Boxes)
            if (frm.doc.docstatus === 0) {
                frm.add_custom_button(
                    __('Purchase Receipt (Store Boxes)'),
                    function () { pick_purchase_receipt(frm); },
                    __('Get Items From')
                );
            }

            queue_sync(frm);
        },

        custom_is_warehouse_storage: function (frm) {
            if (is_work_order_entry(frm)) return;
            if (!frm.doc[FLAG]) queue_sync(frm);
        },

        custom_same_location: function (frm) {

            if (is_work_order_entry(frm)) {
                frappe.show_alert({
                    message: __('Same Location changes are disabled for Work Order-linked Stock Entries.'),
                    indicator: 'orange'
                });
                return;
            }

            if (frm.doc[SAME_LOCATION_FLAG]) {
                copy_same_item_locations(frm);
            } else {
                restore_original_locations(frm);
            }
        },

        items_add: function (frm) {
            if (!is_work_order_entry(frm)) queue_sync(frm);
        },

        items_remove: function (frm) {
            if (!is_work_order_entry(frm)) queue_sync(frm);
        },

        validate: function (frm) {
            if (!is_work_order_entry(frm) && !frm.doc[FLAG]) {
                sync_target_warehouses(frm);
            }
            validate_target_warehouse(frm);
        }
    });

    // --------------------------------------------------
    // STOCK ENTRY DETAIL EVENTS
    // --------------------------------------------------

    frappe.ui.form.on('Stock Entry Detail', {
        item_code: function (frm) { if (!is_work_order_entry(frm)) queue_sync(frm); },
        qty: function (frm) { if (!is_work_order_entry(frm)) queue_sync(frm); },
        s_warehouse: function (frm) { if (!is_work_order_entry(frm)) queue_sync(frm); },
        t_warehouse: function (frm) { if (!is_work_order_entry(frm)) queue_sync(frm); },
        uom: function (frm) { if (!is_work_order_entry(frm)) queue_sync(frm); },
        stock_uom: function (frm) { if (!is_work_order_entry(frm)) queue_sync(frm); }
    });

    // --------------------------------------------------
    // STORAGE LOCATION CHILD EVENTS
    // --------------------------------------------------

    function on_location_edit(frm, cdt, cdn) {

        if (is_work_order_entry(frm)) return;

        // the user edited this row by hand
        mark_manual(frm, locals[cdt][cdn]);

        if (frm.doc[SAME_LOCATION_FLAG]) {
            copy_location_for_same_item(frm, cdn);
        }
    }

    frappe.ui.form.on('Stock Entry Storage Location', {

        item: function (frm) {
            if (is_work_order_entry(frm)) return;
            if (frm.doc[SAME_LOCATION_FLAG]) copy_same_item_locations(frm);
            if (!frm.doc[FLAG]) sync_target_warehouses(frm);
        },

        warehouse: function (frm, cdt, cdn) {
            on_location_edit(frm, cdt, cdn);
            if (!is_work_order_entry(frm) && !frm.doc[FLAG]) {
                sync_target_warehouses(frm);
            }
        },

        floor: function (frm, cdt, cdn) { on_location_edit(frm, cdt, cdn); },
        area: function (frm, cdt, cdn) { on_location_edit(frm, cdt, cdn); },
        shelf: function (frm, cdt, cdn) { on_location_edit(frm, cdt, cdn); },
        rack: function (frm, cdt, cdn) { on_location_edit(frm, cdt, cdn); }
    });

    // --------------------------------------------------
    // GET ITEMS FROM PURCHASE RECEIPT
    // --------------------------------------------------

    function pick_purchase_receipt(frm) {

        frappe.prompt(
            {
                fieldname: 'purchase_receipt',
                label: __('Purchase Receipt'),
                fieldtype: 'Link',
                options: 'Purchase Receipt',
                reqd: 1,
                get_query: function () {
                    return { filters: { docstatus: 1 } };
                }
            },
            function (values) {
                load_from_purchase_receipt(frm, values.purchase_receipt);
            },
            __('Get Items From Purchase Receipt'),
            __('Get Items')
        );
    }

    async function load_from_purchase_receipt(frm, pr_name) {

        var pr = await frappe.db.get_doc('Purchase Receipt', pr_name);

        // qty already moved by submitted Stock Entries from this receipt
        var done = await frappe.db.get_list('Stock Entry Detail', {
            parent: 'Stock Entry',
            filters: {
                reference_purchase_receipt: pr_name,
                docstatus: 1
            },
            fields: ['item_code', 'qty'],
            limit: 0
        });

        var moved = {};
        (done || []).forEach(function (r) {
            moved[r.item_code] = (moved[r.item_code] || 0) + flt(r.qty);
        });

        var lines = [];
        (pr.items || []).forEach(function (d) {
            var qty = flt(d.stock_qty) - flt(moved[d.item_code] || 0);
            if (qty > 0) lines.push({ d: d, qty: qty });
        });

        if (!lines.length) {
            frappe.msgprint(__('Everything on this Purchase Receipt is already stored.'));
            return;
        }

        await frm.set_value('stock_entry_type', 'Material Transfer');
        await frm.set_value('purchase_receipt_no', pr_name);

        // drop the empty default row, keep any real rows
        var has_real_rows = (frm.doc.items || []).some(function (r) {
            return !!r.item_code;
        });

        if (!has_real_rows) {
            frm.clear_table('items');
        }

        lines.forEach(function (line) {
            frm.add_child('items', {
                item_code: line.d.item_code,
                item_name: line.d.item_name,
                qty: line.qty,
                transfer_qty: line.qty,
                uom: line.d.stock_uom,
                stock_uom: line.d.stock_uom,
                conversion_factor: 1,
                s_warehouse: line.d.warehouse,   // target stays empty on purpose
                basic_rate: line.d.valuation_rate || line.d.rate,
                reference_purchase_receipt: pr_name
            });
        });

        frm.refresh_field('items');

        clearTimeout(frm.__loc_timer);
        sync_locations(frm);
    }

    // --------------------------------------------------
    // DELAY SYNCHRONIZATION
    // --------------------------------------------------

    function queue_sync(frm) {

        if (frm.doc.docstatus !== 0) return;
        if (is_work_order_entry(frm)) return;

        clearTimeout(frm.__loc_timer);

        frm.__loc_timer = setTimeout(function () {
            sync_locations(frm);
        }, 800);
    }

    // --------------------------------------------------
    // GENERATE STORAGE LOCATION ROWS (ONE ROW PER WHOLE UNIT)
    // --------------------------------------------------

    function sync_locations(frm) {

        if (frm.doc.docstatus !== 0 || frm.doc[FLAG] || is_work_order_entry(frm)) {
            return;
        }

        var wanted = [];
        var counts = {};

        (frm.doc.items || []).forEach(function (d) {

            if (!d.item_code) return;

            var warehouse = d.t_warehouse || '';
            var qty = Math.max(0, Math.floor(flt(d.qty)));

            for (var i = 0; i < qty; i++) {

                counts[d.item_code] = (counts[d.item_code] || 0) + 1;

                wanted.push({
                    key: d.item_code + '#' + counts[d.item_code],
                    item: d.item_code,
                    warehouse: warehouse,
                    uom: d.stock_uom || d.uom || '',
                    quantity: 1
                });
            }
        });

        var rows = frm.doc[TABLE] || [];
        var kept = {};
        var seen = {};

        rows.forEach(function (r) {

            var item = r[F.item];
            seen[item] = (seen[item] || 0) + 1;

            var values = {};

            Object.keys(r).forEach(function (field) {
                if (SKIP.indexOf(field) === -1) {
                    values[field] = r[field];
                }
            });

            kept[item + '#' + seen[item]] = values;
        });

        var unchanged =
            rows.length === wanted.length &&
            wanted.every(function (w, i) {
                return rows[i][F.item] === w.item &&
                    flt(rows[i][F.qty]) === 1 &&
                    (rows[i][F.uom] || '') === w.uom;
            });

        if (unchanged) {
            if (frm.doc[SAME_LOCATION_FLAG]) {
                copy_same_item_locations(frm);
            }
            return;
        }

        frm.clear_table(TABLE);

        wanted.forEach(function (w) {

            var values = Object.assign({}, kept[w.key] || {});

            values[F.item] = w.item;
            values[F.uom] = w.uom;
            values[F.qty] = 1;

            // existing rows keep their own warehouse; new rows get the item's target
            if (!values[F.warehouse]) {
                values[F.warehouse] = w.warehouse;
            }

            frm.add_child(TABLE, values);
        });

        frm.refresh_field(TABLE);

        if (frm.doc[SAME_LOCATION_FLAG]) {
            copy_same_item_locations(frm);
        }

        sync_target_warehouses(frm);
    }

    // --------------------------------------------------
    // UNTICK: REMOVE ONLY THE ROWS THE CHECKBOX FILLED
    // manual rows stay; overwritten manual values come back
    // --------------------------------------------------

    function restore_original_locations(frm) {

        ensure_state(frm);

        var map = row_key_map(frm);
        var cleared = 0;

        (frm.doc[TABLE] || []).forEach(function (row) {

            var key = map[row.name];

            if (!key || !frm.__auto[key]) return;

            var backup = frm.__backup[key];

            LOCATION_FIELDS.forEach(function (f) {
                row[f] = backup ? (backup[f] || '') : '';
            });

            cleared++;
        });

        frm.__auto = {};
        frm.__backup = {};

        frm.refresh_field(TABLE);

        if (!frm.doc[FLAG]) sync_target_warehouses(frm);

        frappe.show_alert({
            message: cleared
                ? __('Removed {0} auto-filled row(s). Manual entries kept.', [cleared])
                : __('No auto-filled rows to remove.'),
            indicator: cleared ? 'green' : 'orange'
        });
    }

    // --------------------------------------------------
    // COPY THE EDITED ROW TO ROWS WITH THE SAME ITEM
    // --------------------------------------------------

    function copy_location_for_same_item(frm, cdn) {

        if (!frm.doc[SAME_LOCATION_FLAG] || is_work_order_entry(frm)) return;

        var rows = frm.doc[TABLE] || [];

        var changed_row = rows.find(function (row) {
            return row.name === cdn;
        });

        if (!changed_row || !changed_row[F.item]) return;

        var map = row_key_map(frm);

        rows.forEach(function (row) {

            if (row.name === changed_row.name || row[F.item] !== changed_row[F.item]) {
                return;
            }

            apply_auto(frm, row, map[row.name], changed_row);
        });

        frm.refresh_field(TABLE);

        if (!frm.doc[FLAG]) sync_target_warehouses(frm);
    }

    // --------------------------------------------------
    // APPLY SAME LOCATION TO EACH ITEM GROUP
    // first row of each item is the source
    // --------------------------------------------------

    function copy_same_item_locations(frm) {

        if (!frm.doc[SAME_LOCATION_FLAG] || is_work_order_entry(frm)) return;

        ensure_state(frm);

        var rows = frm.doc[TABLE] || [];
        var map = row_key_map(frm);
        var first_row_by_item = {};

        rows.forEach(function (row) {

            var item = row[F.item];
            if (!item) return;

            if (!first_row_by_item[item]) {
                first_row_by_item[item] = row;
                return;
            }

            apply_auto(frm, row, map[row.name], first_row_by_item[item]);
        });

        frm.refresh_field(TABLE);

        if (!frm.doc[FLAG]) sync_target_warehouses(frm);
    }

    // --------------------------------------------------
    // STORAGE LOCATION WAREHOUSE -> TARGET WAREHOUSE
    // --------------------------------------------------

    function sync_target_warehouses(frm) {

        if (frm.doc.docstatus !== 0 || frm.doc[FLAG] || is_work_order_entry(frm)) {
            return;
        }

        var locations = frm.doc[TABLE] || [];
        var items = frm.doc.items || [];

        items.forEach(function (item_row) {

            if (!item_row.item_code) return;

            var location = locations.find(function (location_row) {
                return location_row[F.item] === item_row.item_code &&
                    !!location_row[F.warehouse];
            });

            if (location) {
                item_row.t_warehouse = location[F.warehouse];
            }
        });

        frm.refresh_field('items');
    }

    // --------------------------------------------------
    // VALIDATE TARGET WAREHOUSE
    // --------------------------------------------------

    function validate_target_warehouse(frm) {

        if (frm.doc.stock_entry_type !== 'Material Transfer') return;

        var missing = [];

        (frm.doc.items || []).forEach(function (row) {
            if (row.item_code && !row.t_warehouse) {
                missing.push(row.idx);
            }
        });

        if (missing.length) {
            frappe.throw(
                __('Please select a Warehouse in the Storage Location table for item row(s): {0}',
                    [missing.join(', ')])
            );
        }
    }

})();

// ==================================================
// SAVE PREVIOUS LOCATIONS FOR CHECKBOX RESTORATION
// ==================================================

let previous_target_locations = {};
let previous_wip_locations = {};
let target_update_token = 0;
let target_poll_running = false;
let required_items_clear_token = 0;


// ==================================================
// LOCATION TABLE CONFIGURATION
// ==================================================

const SOURCE_TABLE = "custom_source_warehouse_storage_location";
const WIP_TABLE = "custom_workinprogress_warehouse_storage_location";
const TARGET_TABLE = "custom_finished_product_storage_location";

const LOCATION_TABLES = [SOURCE_TABLE, WIP_TABLE, TARGET_TABLE];

// Tables affected by "Same Storage For All Item"
const SAME_STORAGE_TABLES = [SOURCE_TABLE];

const LOCATION_FIELDS = [
    "warehouse",
    "floor",
    "area",
    "shelf",
    "rack"
];

const registered_row_doctypes = {};


// ==================================================
// AUTO-FILL TRACKING FOR "SAME STORAGE FOR ALL ITEMS"
// frm.__same_auto[table][key]   = true -> row was filled by the checkbox
// frm.__same_backup[table][key] = {...} -> manual values the tick overwrote
// key = item#occurrence (stays stable when tables are rebuilt)
// ==================================================

function ensure_same_state(frm) {
    if (!frm.__same_auto) frm.__same_auto = {};
    if (!frm.__same_backup) frm.__same_backup = {};

    LOCATION_TABLES.forEach(table => {
        if (!frm.__same_auto[table]) frm.__same_auto[table] = {};
        if (!frm.__same_backup[table]) frm.__same_backup[table] = {};
    });
}

function row_key_map(frm, table) {
    const counts = {};
    const map = {};

    (frm.doc[table] || []).forEach(row => {
        if (!row.item) {
            return;
        }

        counts[row.item] = (counts[row.item] || 0) + 1;
        map[row.name] = row.item + "#" + counts[row.item];
    });

    return map;
}

function has_location(row) {
    return LOCATION_FIELDS.some(field => !!row[field]);
}

// Copy source location into row and remember it as auto-filled
function apply_auto(frm, table, row, key, source) {
    ensure_same_state(frm);

    const auto = frm.__same_auto[table];
    const backup = frm.__same_backup[table];

    // Keep the user's own values so unticking can bring them back
    if (!auto[key] && has_location(row) && !backup[key]) {
        backup[key] = {};

        LOCATION_FIELDS.forEach(field => {
            backup[key][field] = row[field] || "";
        });
    }

    LOCATION_FIELDS.forEach(field => {
        row[field] = source[field] || "";
    });

    auto[key] = true;
}

// The user typed in this row -> it is manual, never cleared on untick
function mark_manual(frm, table, row) {
    ensure_same_state(frm);

    const key = row_key_map(frm, table)[row.name];

    if (!key) {
        return;
    }

    delete frm.__same_auto[table][key];
    delete frm.__same_backup[table][key];
}


// ==================================================
// WORK ORDER EVENTS
// ==================================================

frappe.ui.form.on("Work Order", {
    setup(frm) {
        register_location_row_events();
    },

    // Page open
    onload(frm) {
        wait_and_update_target_locations(frm);
        clear_required_item_warehouses(frm);
    },

    // Page fully rendered
    onload_post_render(frm) {
        wait_and_update_target_locations(frm);
    },

    // Production Item
    production_item(frm) {
        update_target_locations(frm);
        clear_required_item_warehouses(frm);
    },

    // Quantity
    qty(frm) {
        update_target_locations(frm);
        wait_and_update_material_locations(frm);
        clear_required_item_warehouses(frm);
    },

    // BOM
    bom_no(frm) {
        wait_and_update_material_locations(frm);
        clear_required_item_warehouses(frm);
    },

    // Same Storage for All Items (Source table only)
    // Ticked   -> copy each item's first manual row to its other rows
    //             (runs only at the moment of ticking)
    // Unticked -> remove only the auto-filled rows, keep manual entries
    custom_same_storage_for_all_item(frm) {
        if (frm.doc.custom_same_storage_for_all_item) {
            fill_same_item_locations(frm);
        } else {
            remove_auto_filled_locations(frm);
        }
    },

    // Same Storage Location Checkbox
    // Only copies the first row's location to all target rows.
    // Rows themselves are already filled when the page opens.
    async custom_same_stroage_location(frm) {
        if (frm.doc.custom_same_stroage_location) {
            save_previous_target_locations(frm);
            copy_first_target_location_to_all(frm);
        } else {
            restore_previous_target_locations(frm);
            await update_target_locations(frm);
        }
    },

    // Same Warehouse Checkbox
    // Ticked   -> save current WIP locations, copy source locations to WIP
    // Unticked -> restore the WIP locations as they were before
    custom_same_warehouse(frm) {
        if (frm.doc.custom_same_warehouse) {
            save_previous_wip_locations(frm);
            copy_source_locations_to_wip(frm);
        } else {
            restore_previous_wip_locations(frm);
        }
    },

    // Before save: push Source table warehouses to Required Items
    before_save(frm) {
        sync_required_item_warehouses(frm);
    },

    // Refresh
    refresh(frm) {
        register_location_row_events();

        if (!can_autofill(frm)) {
            return;
        }

        wait_and_update_target_locations(frm);

        // Build Source / WIP tables only when new or empty,
        // so a saved Work Order is not marked "Not Saved" again
        if (
            frm.doc.required_items?.length &&
            (frm.is_new() ||
                !(frm.doc[SOURCE_TABLE] || []).length ||
                !(frm.doc[WIP_TABLE] || []).length)
        ) {
            update_material_locations(frm);
        }
    }
});


// ==================================================
// FORM KEY
// ==================================================

function get_work_order_key(frm) {
    return frm.doc.name || frm.doc.__unsaved || "new_work_order";
}


// ==================================================
// SAVE PREVIOUS WIP LOCATIONS
// Called when "Same Warehouse" is ticked
// ==================================================

function save_previous_wip_locations(frm) {
    const key = get_work_order_key(frm);

    previous_wip_locations[key] =
        (frm.doc[WIP_TABLE] || []).map(row => ({
            item: row.item,
            warehouse: row.warehouse,
            floor: row.floor,
            area: row.area,
            shelf: row.shelf,
            rack: row.rack
        }));
}


// ==================================================
// RESTORE PREVIOUS WIP LOCATIONS
// Called when "Same Warehouse" is unticked
// ==================================================

function restore_previous_wip_locations(frm) {
    const key = get_work_order_key(frm);
    const saved_rows = previous_wip_locations[key];
    const wip_rows = frm.doc[WIP_TABLE] || [];

    if (!wip_rows.length) {
        delete previous_wip_locations[key];
        return;
    }

    if (saved_rows && saved_rows.length) {
        const saved_by_item = {};

        saved_rows.forEach(data => {
            if (!data.item) {
                return;
            }

            if (!saved_by_item[data.item]) {
                saved_by_item[data.item] = [];
            }

            saved_by_item[data.item].push(data);
        });

        const item_indexes = {};

        wip_rows.forEach(row => {
            if (!row.item) {
                return;
            }

            const list = saved_by_item[row.item];
            const index = item_indexes[row.item] || 0;

            item_indexes[row.item] = index + 1;

            if (!list || !list[index]) {
                row.warehouse = "";
                row.floor = "";
                row.area = "";
                row.shelf = "";
                row.rack = "";
                return;
            }

            const data = list[index];

            row.warehouse = data.warehouse || "";
            row.floor = data.floor || "";
            row.area = data.area || "";
            row.shelf = data.shelf || "";
            row.rack = data.rack || "";
        });
    } else {
        wip_rows.forEach(row => {
            row.warehouse = "";
            row.floor = "";
            row.area = "";
            row.shelf = "";
            row.rack = "";
        });
    }

    frm.refresh_field(WIP_TABLE);

    delete previous_wip_locations[key];
}


// ==================================================
// SAVE PREVIOUS TARGET (FINISHED PRODUCT) LOCATIONS
// ==================================================

function save_previous_target_locations(frm) {
    const key = get_work_order_key(frm);

    previous_target_locations[key] =
        (frm.doc[TARGET_TABLE] || []).map(row => ({
            item: row.item,
            warehouse: row.warehouse,
            floor: row.floor,
            area: row.area,
            shelf: row.shelf,
            rack: row.rack,
            uom: row.uom,
            quantity: row.quantity
        }));
}


// ==================================================
// RESTORE PREVIOUS TARGET (FINISHED PRODUCT) LOCATIONS
// ==================================================

function restore_previous_target_locations(frm) {
    const key = get_work_order_key(frm);
    const previous = previous_target_locations[key];

    if (!previous) {
        return;
    }

    frm.clear_table(TARGET_TABLE);

    previous.forEach(data => {
        const row = frm.add_child(TARGET_TABLE);

        row.item = data.item || "";
        row.warehouse = data.warehouse || "";
        row.floor = data.floor || "";
        row.area = data.area || "";
        row.shelf = data.shelf || "";
        row.rack = data.rack || "";
        row.uom = data.uom || "";
        row.quantity = data.quantity ?? 0;
    });

    frm.refresh_field(TARGET_TABLE);

    delete previous_target_locations[key];
}


// ==================================================
// CHECKBOX HELPERS
// ==================================================

function can_autofill(frm) {
    return frm.doc.docstatus === 0 && (frm.is_new() || frm.is_dirty());
}

function same_storage_enabled(frm) {
    return !!frm.doc.custom_same_storage_for_all_item;
}

function same_location_enabled(frm) {
    return !!frm.doc.custom_same_stroage_location;
}


// ==================================================
// SPLIT QUANTITY INTO INDIVIDUAL UNITS
// ==================================================

function expand_quantity(total) {
    const result = [];
    let remaining = flt(total, 6);

    while (remaining > 0.000001) {
        const quantity = Math.min(1, remaining);

        result.push(flt(quantity, 6));

        remaining = flt(remaining - quantity, 6);
    }

    return result;
}


// ==================================================
// CLEAR THE DEFAULT SOURCE WAREHOUSE IN REQUIRED ITEMS
// ==================================================

function clear_required_item_warehouses(frm) {
    if (frm.doc.docstatus !== 0 || !frm.is_new()) {
        return;
    }

    const token = ++required_items_clear_token;

    const run = attempt => {
        if (token !== required_items_clear_token) {
            return;
        }

        if (frm.doc.docstatus !== 0 || !frm.is_new()) {
            return;
        }

        const chosen = new Set(
            (frm.doc[SOURCE_TABLE] || [])
                .filter(row => row.warehouse)
                .map(row => row.item)
        );

        let changed = false;

        (frm.doc.required_items || []).forEach(req => {
            if (req.source_warehouse && !chosen.has(req.item_code)) {
                req.source_warehouse = "";
                changed = true;
            }
        });

        if (changed) {
            frm.refresh_field("required_items");
        }

        if (attempt < 12) {
            setTimeout(() => run(attempt + 1), 500);
        }
    };

    setTimeout(() => run(0), 300);
}


// ==================================================
// WAIT FOR REQUIRED ITEMS TO LOAD
// ==================================================

function wait_and_update_material_locations(frm, attempt = 0) {
    if (attempt >= 20) {
        if (frm.doc.required_items?.length) {
            update_material_locations(frm);
        }

        return;
    }

    setTimeout(() => {
        if (frm.doc.required_items?.length) {
            update_material_locations(frm);
        } else {
            wait_and_update_material_locations(frm, attempt + 1);
        }
    }, 500);
}


// ==================================================
// WAIT FOR PRODUCTION ITEM, THEN FILL TARGET TABLE
// ==================================================

function wait_and_update_target_locations(frm, attempt = 0) {
    if (!can_autofill(frm)) {
        target_poll_running = false;
        return;
    }

    if (attempt === 0) {
        if (target_poll_running) {
            return;
        }
        target_poll_running = true;
    }

    if (frm.doc.production_item) {
        target_poll_running = false;
        update_target_locations(frm);
        return;
    }

    if (attempt >= 20) {
        target_poll_running = false;
        return;
    }

    setTimeout(() => {
        wait_and_update_target_locations(frm, attempt + 1);
    }, 500);
}


// ==================================================
// FINISHED PRODUCT STORAGE LOCATIONS (TARGET TABLE)
// ==================================================

async function update_target_locations(frm, force = false) {
    if (frm.doc.docstatus !== 0) {
        return;
    }

    const item_code = frm.doc.production_item;

    if (!item_code) {
        return;
    }

    const token = ++target_update_token;

    const quantities = expand_quantity(flt(frm.doc.qty) || 1);
    const old_rows = (frm.doc[TARGET_TABLE] || []).map(row => ({ ...row }));

    const in_sync =
        old_rows.length === quantities.length &&
        old_rows.every(
            (row, i) =>
                row.item === item_code &&
                flt(row.quantity, 6) === quantities[i]
        );

    if (in_sync && !force) {
        return;
    }

    let stock_uom = "";

    if (old_rows[0] && old_rows[0].item === item_code && old_rows[0].uom) {
        stock_uom = old_rows[0].uom;
    } else {
        const response = await frappe.db.get_value(
            "Item",
            item_code,
            "stock_uom"
        );

        stock_uom = response.message?.stock_uom || "";
    }

    if (token !== target_update_token) {
        return;
    }

    frm.clear_table(TARGET_TABLE);

    quantities.forEach((quantity, index) => {
        const row = frm.add_child(TARGET_TABLE);

        const source_row = old_rows[index] || {};

        row.item = item_code;

        // Warehouse is NOT autofilled - it is chosen by the user
        row.warehouse = source_row.warehouse || "";

        row.floor = source_row.floor || "";
        row.area = source_row.area || "";
        row.shelf = source_row.shelf || "";
        row.rack = source_row.rack || "";

        row.uom = stock_uom;
        row.quantity = quantity;
    });

    frm.refresh_field(TARGET_TABLE);
}


// ==================================================
// COPY FIRST TARGET ROW LOCATION TO ALL TARGET ROWS
// Used by "Same Stroage Location" checkbox
// ==================================================

function copy_first_target_location_to_all(frm) {
    const rows = frm.doc[TARGET_TABLE] || [];

    if (rows.length < 2) {
        return;
    }

    const first = rows[0];

    rows.slice(1).forEach(row => {
        LOCATION_FIELDS.forEach(field => {
            row[field] = first[field] || "";
        });
    });

    frm.refresh_field(TARGET_TABLE);
}


// ==================================================
// SOURCE AND WORK-IN-PROGRESS LOCATION TABLES
// ==================================================

function update_material_locations(frm) {
    const required_items = frm.doc.required_items || [];

    if (!required_items.length) {
        return;
    }

    const old_source = frm.doc[SOURCE_TABLE] || [];
    const old_wip = frm.doc[WIP_TABLE] || [];

    const source_map = {};
    const wip_map = {};

    old_source.forEach(row => {
        if (row.item && !source_map[row.item]) {
            source_map[row.item] = { ...row };
        }
    });

    old_wip.forEach(row => {
        if (row.item && !wip_map[row.item]) {
            wip_map[row.item] = { ...row };
        }
    });

    frm.clear_table(SOURCE_TABLE);
    frm.clear_table(WIP_TABLE);

    for (const required of required_items) {
        const item_code = required.item_code;

        if (!item_code) {
            continue;
        }

        const quantities = expand_quantity(required.required_qty);

        const source_old = source_map[item_code] || {};
        const wip_old = wip_map[item_code] || {};

        for (const quantity of quantities) {
            const source = frm.add_child(SOURCE_TABLE);

            source.item = item_code;
            source.warehouse = source_old.warehouse || "";
            source.floor = source_old.floor || "";
            source.area = source_old.area || "";
            source.shelf = source_old.shelf || "";
            source.rack = source_old.rack || "";
            source.uom = required.stock_uom || "";
            source.quantity = quantity;

            const wip = frm.add_child(WIP_TABLE);

            wip.item = item_code;
            wip.warehouse = wip_old.warehouse || "";
            wip.floor = wip_old.floor || "";
            wip.area = wip_old.area || "";
            wip.shelf = wip_old.shelf || "";
            wip.rack = wip_old.rack || "";
            wip.uom = required.stock_uom || "";
            wip.quantity = quantity;
        }
    }

    frm.refresh_field(SOURCE_TABLE);
    frm.refresh_field(WIP_TABLE);
}


// ==================================================
// COPY SOURCE LOCATIONS TO WIP
// ==================================================

function copy_source_locations_to_wip(frm) {
    const source_rows = frm.doc[SOURCE_TABLE] || [];
    const wip_rows = frm.doc[WIP_TABLE] || [];

    const source_locations = {};

    source_rows.forEach(source => {
        if (!source.item) {
            return;
        }

        if (!source_locations[source.item]) {
            source_locations[source.item] = [];
        }

        source_locations[source.item].push(source);
    });

    const item_indexes = {};

    wip_rows.forEach(wip => {
        if (!wip.item) {
            return;
        }

        const matching_sources = source_locations[wip.item];

        if (!matching_sources || !matching_sources.length) {
            return;
        }

        const index = item_indexes[wip.item] || 0;

        const source = matching_sources[
            Math.min(index, matching_sources.length - 1)
        ];

        item_indexes[wip.item] = index + 1;

        wip.warehouse = source.warehouse || "";
        wip.floor = source.floor || "";
        wip.area = source.area || "";
        wip.shelf = source.shelf || "";
        wip.rack = source.rack || "";
    });

    frm.refresh_field(WIP_TABLE);
}


// ==================================================
// REGISTER CHILD TABLE LOCATION EVENTS
// ==================================================

function register_location_row_events() {
    LOCATION_TABLES.forEach(table => {
        const df = frappe.meta.get_docfield("Work Order", table);

        if (!df || !df.options) {
            return;
        }

        if (registered_row_doctypes[df.options]) {
            return;
        }

        registered_row_doctypes[df.options] = true;

        const handlers = {};

        LOCATION_FIELDS.forEach(field => {
            handlers[field] = (frm, cdt, cdn) => {
                copy_row_to_same_item(frm, cdt, cdn);
            };
        });

        frappe.ui.form.on(df.options, handlers);
    });
}


// ==================================================
// COPY LOCATIONS BETWEEN ROWS
// - the edited row becomes a MANUAL row (kept on untick)
// - NO autofill while typing: "Same Storage For All Item" fills the
//   Source table only at the moment the checkbox is ticked
// - Target table only fills when the "Same Stroage Location"
//   checkbox is clicked
// - Source table edits are synced to Required Items
// ==================================================

function copy_row_to_same_item(frm, cdt, cdn) {
    if (frm.doctype !== "Work Order") {
        return;
    }

    const row = locals[cdt]?.[cdn];

    if (!row || !LOCATION_TABLES.includes(row.parentfield)) {
        return;
    }

    const table = row.parentfield;

    // The user edited this row by hand
    mark_manual(frm, table, row);

    // Source table: keep Required Items warehouse in sync
    if (table === SOURCE_TABLE) {
        setTimeout(() => sync_required_item_warehouses(frm), 0);
    }

    // No autofill while typing in any table.
    // "Same Storage For All Item" fills only when the checkbox is ticked.
}


// ==================================================
// FILL LOCATIONS FOR SAME ITEMS WITHIN THE SOURCE TABLE
// The first row WITH location data that was not auto-filled
// is the source for the other rows of that item.
// ==================================================

function fill_same_item_locations(frm) {
    if (!same_storage_enabled(frm)) {
        return;
    }

    ensure_same_state(frm);

    SAME_STORAGE_TABLES.forEach(table => {
        const rows = frm.doc[table] || [];
        const map = row_key_map(frm, table);
        const auto = frm.__same_auto[table];
        const master = {};

        rows.forEach(row => {
            if (!row.item || master[row.item]) {
                return;
            }

            if (has_location(row) && !auto[map[row.name]]) {
                master[row.item] = row;
            }
        });

        rows.forEach(row => {
            const first = master[row.item];

            if (!first || first === row) {
                return;
            }

            apply_auto(frm, table, row, map[row.name], first);
        });

        frm.refresh_field(table);
    });

    sync_required_item_warehouses(frm);
}


// ==================================================
// UNTICK: REMOVE ONLY THE ROWS THE CHECKBOX FILLED
// Manual rows stay; manual values the tick overwrote come back.
// ==================================================

function remove_auto_filled_locations(frm) {
    ensure_same_state(frm);

    let cleared = 0;

    SAME_STORAGE_TABLES.forEach(table => {
        const map = row_key_map(frm, table);
        const auto = frm.__same_auto[table];
        const backup = frm.__same_backup[table];

        (frm.doc[table] || []).forEach(row => {
            const key = map[row.name];

            if (!key || !auto[key]) {
                return;
            }

            LOCATION_FIELDS.forEach(field => {
                row[field] = backup[key] ? (backup[key][field] || "") : "";
            });

            cleared++;
        });

        frm.__same_auto[table] = {};
        frm.__same_backup[table] = {};

        frm.refresh_field(table);
    });

    frappe.show_alert({
        message: cleared
            ? __("Removed {0} auto-filled row(s). Manual entries kept.", [cleared])
            : __("No auto-filled rows to remove."),
        indicator: cleared ? "green" : "orange"
    });
}


// ==================================================
// SYNC SOURCE TABLE WAREHOUSE -> REQUIRED ITEMS
// ==================================================

function sync_required_item_warehouses(frm) {
    if (frm.doc.docstatus !== 0) {
        return;
    }

    const warehouse_by_item = {};

    (frm.doc[SOURCE_TABLE] || []).forEach(row => {
        if (row.item && row.warehouse && !warehouse_by_item[row.item]) {
            warehouse_by_item[row.item] = row.warehouse;
        }
    });

    let changed = false;

    (frm.doc.required_items || []).forEach(req => {
        const warehouse = warehouse_by_item[req.item_code];

        if (warehouse && req.source_warehouse !== warehouse) {
            req.source_warehouse = warehouse;
            changed = true;
        }
    });

    if (changed) {
        frm.refresh_field("required_items");
    }
}

