const WO_LOCATION_TABLES = [
    "custom_source_warehouse_storage_location",
    "custom_workinprogress_warehouse_storage_location"
];

const NO_MATCH = { filters: { name: ["=", "__no_matching_location__"] } };

// Builds the filter: every field in the list must already be chosen in the row,
// and the list shows only the records that belong to those values.
function wo_location_query(required_fields) {
    return function (doc, cdt, cdn) {
        const row = locals[cdt][cdn];
        const filters = {};

        for (const fieldname of required_fields) {
            if (!row[fieldname]) {
                return NO_MATCH;
            }
            filters[fieldname] = row[fieldname];
        }

        return { filters };
    };
}

// Rack list: narrow by any parent already selected (none are mandatory),
// so a rack can be picked first
function wo_rack_query(doc, cdt, cdn) {
    const row = locals[cdt][cdn];
    const filters = {};

    ["warehouse", "floor", "area", "shelf"].forEach(fieldname => {
        if (row[fieldname]) {
            filters[fieldname] = row[fieldname];
        }
    });

    return { filters };
}

