    if (window.__se_location_clear_registered[df.options]) {
        return;
    }

    window.__se_location_clear_registered[df.options] = true;

    frappe.ui.form.on(df.options, {
        warehouse(frm, cdt, cdn) {
            clear_se_location_fields(frm, cdt, cdn, ["floor", "area", "shelf", "rack"]);
        },

        floor(frm, cdt, cdn) {
            clear_se_location_fields(frm, cdt, cdn, ["area", "shelf", "rack"]);
        },

        area(frm, cdt, cdn) {
            clear_se_location_fields(frm, cdt, cdn, ["shelf", "rack"]);
        },

        shelf(frm, cdt, cdn) {
