// When a field changes, clear the fields below it.
function clear_se_location_fields(frm, cdt, cdn, fields) {
    if (frm.doctype !== "Stock Entry") {
        return;
    }

    // Skip while the rack is auto-filling the parents
    if (window.__se_location_autofilling) {
        return;
    }

    fields.forEach(fieldname => {
        const row = locals[cdt][cdn];

        if (row && row[fieldname]) {
            frappe.model.set_value(cdt, cdn, fieldname, "");
        }
    });
}


async function autofill_se_location_from_rack(frm, cdt, cdn) {
    if (frm.doctype !== "Stock Entry" || window.__se_location_autofilling) {
        return;
    }

    const row = locals[cdt][cdn];

    if (!row || !row.rack) {
        return;
    }

    // Find the doctype that the "rack" link field points to
    const rack_df = frappe.meta.get_docfield(cdt, "rack");
    const rack_doctype = rack_df && rack_df.options;

    if (!rack_doctype) {
        return;
    }

    const r = await frappe.db.get_value(
        rack_doctype,
        row.rack,
        ["warehouse", "floor", "area", "shelf"]
    );

    const values = r && r.message;

    if (!values) {
        return;
    }

    window.__se_location_autofilling = true;

    try {
        for (const fieldname of ["warehouse", "floor", "area", "shelf"]) {
            if (values[fieldname] && row[fieldname] !== values[fieldname]) {
                await frappe.model.set_value(cdt, cdn, fieldname, values[fieldname]);
            }
        }
    } finally {
        window.__se_location_autofilling = false;
    }
}

