// Service Entry: cascading location filters
// Warehouse -> Floor -> Area -> Shelf -> Rack
// Selecting a Rack auto-fills Warehouse, Floor, Area and Shelf

(function () {
    const PARENT_DOCTYPE = "Service Entry";
    const CHILD_TABLE = "serviced_items";
    const LOCATION_PARENTS = ["warehouse", "floor", "area", "shelf"];

    frappe.ui.form.on(PARENT_DOCTYPE, {
        setup(frm) {
            set_serviced_item_location_filters(frm);
        },

        refresh(frm) {
            set_serviced_item_location_filters(frm);
        },

        onload(frm) {
            set_serviced_item_location_filters(frm);
        }
    });

    function set_serviced_item_location_filters(frm) {
        frm.set_query("floor", CHILD_TABLE, function (doc, cdt, cdn) {
            return build_location_filter(cdt, cdn, ["warehouse"]);
        });

        frm.set_query("area", CHILD_TABLE, function (doc, cdt, cdn) {
            return build_location_filter(cdt, cdn, ["warehouse", "floor"]);
        });

        frm.set_query("shelf", CHILD_TABLE, function (doc, cdt, cdn) {
            return build_location_filter(cdt, cdn, ["warehouse", "floor", "area"]);
        });

        // Rack: no required parents, filter only by the ones already selected
        frm.set_query("rack", CHILD_TABLE, function (doc, cdt, cdn) {
            const row = locals[cdt][cdn];
            const filters = {};

            LOCATION_PARENTS.forEach(fieldname => {
                if (row[fieldname]) {
                    filters[fieldname] = row[fieldname];
                }
            });

            return { filters };
        });
    }

    function build_location_filter(cdt, cdn, required_fields) {
        const row = locals[cdt][cdn];
        const filters = {};

        // Do not show any choices until all parent fields are selected.
        for (const fieldname of required_fields) {
            if (!row[fieldname]) {
                return {
                    filters: {
                        name: ["=", "__no_matching_location__"]
                    }
                };
            }

            filters[fieldname] = row[fieldname];
        }

        return { filters };
    }

    // Clear dependent location fields when a parent changes.
    frappe.ui.form.on("Storage Location", {
        warehouse(frm, cdt, cdn) {
            if (frm.doctype !== PARENT_DOCTYPE) return;

            clear_location_fields(cdt, cdn, ["floor", "area", "shelf", "rack"]);
        },

        floor(frm, cdt, cdn) {
            if (frm.doctype !== PARENT_DOCTYPE) return;

            clear_location_fields(cdt, cdn, ["area", "shelf", "rack"]);
        },

        area(frm, cdt, cdn) {
            if (frm.doctype !== PARENT_DOCTYPE) return;

            clear_location_fields(cdt, cdn, ["shelf", "rack"]);
        },

        shelf(frm, cdt, cdn) {
            if (frm.doctype !== PARENT_DOCTYPE) return;

            clear_location_fields(cdt, cdn, ["rack"]);
        },

        // Rack selected -> fill all parents
        rack(frm, cdt, cdn) {
            if (frm.doctype !== PARENT_DOCTYPE) return;

            autofill_location_from_rack(cdt, cdn);
        }
    });

    function clear_location_fields(cdt, cdn, fields) {
        // Skip while the rack is auto-filling the parents
        if (window.__svc_location_autofilling) return;

        const row = locals[cdt][cdn];

        if (!row) return;

        fields.forEach(fieldname => {
            if (row[fieldname]) {
                frappe.model.set_value(cdt, cdn, fieldname, "");
            }
        });
    }

    async function autofill_location_from_rack(cdt, cdn) {
        if (window.__svc_location_autofilling) return;

        const row = locals[cdt][cdn];

        if (!row || !row.rack) return;

        // Find the doctype that the "rack" link field points to
        const rack_df = frappe.meta.get_docfield(cdt, "rack");
        const rack_doctype = rack_df && rack_df.options;

        if (!rack_doctype) return;

        const r = await frappe.db.get_value(rack_doctype, row.rack, LOCATION_PARENTS);
        const values = r && r.message;

        if (!values) return;

        window.__svc_location_autofilling = true;

        try {
            for (const fieldname of LOCATION_PARENTS) {
                if (values[fieldname] && row[fieldname] !== values[fieldname]) {
                    await frappe.model.set_value(cdt, cdn, fieldname, values[fieldname]);
                }
            }
        } finally {
            window.__svc_location_autofilling = false;
        }
    }
})();

const TEARDOWN_DOCTYPE = "Vehicle Tear Down";
const RECOVERED_PARTS_DOCTYPE = "Recovered Spare Part";

// Anything that is not "Scrap" counts as reusable, whatever the label is.
function is_reusable(row) {
    return Boolean(row.disposition) && row.disposition !== "Scrap";
}


// ============================================================
// VEHICLE TEAR DOWN
// ============================================================

frappe.ui.form.on(TEARDOWN_DOCTYPE, {
    setup(frm) {
        // Show only active serial numbers that have a warehouse.
        frm.set_query("vehicle_serial_no", () => ({
            filters: {
                status: "Active",
                warehouse: ["is", "set"]
            }
        }));
    },

    onload(frm) {
        // Parent Item fieldname is "item", NOT "item_code".
        if (frm.doc.vehicle_serial_no && !frm.doc.item) {
            fetch_vehicle_details(frm);
        }
    },

    refresh(frm) {
        // Rows loaded by code do not fire row events, so sync here too.
        sync_reusable_parts(frm);
    },

    vehicle_serial_no(frm) {
        fetch_vehicle_details(frm);
    },

    recovered_parts_add(frm) {
        sync_reusable_parts(frm);
    },

    recovered_parts_remove(frm) {
        sync_reusable_parts(frm);
    },

    validate(frm) {
        if (frm.doc.docstatus !== 0) {
            return;
        }

        fill_missing_destinations(frm);
        sync_reusable_parts(frm);

        // Every reusable part needs a Destination Warehouse.
        const missing = (frm.doc.recovered_parts || []).filter(row =>
            is_reusable(row) && row.item_code && !row.destination_warehouse
        );

        if (missing.length) {
            frappe.throw(
                __("Please select a Destination Warehouse for every reusable part.")
            );
        }

        // Every reusable part needs a shelf (remove this block if drafts
        // without a shelf should be allowed; the server still checks on Submit).
        const no_shelf = (frm.doc.storage_location || []).filter(
            row => row.item && !row.shelf
        );

        if (no_shelf.length) {
            frappe.throw(
                __("Choose the floor, area and shelf for: {0}", [
                    no_shelf.map(row => row.item).join(", ")
                ])
            );
        }
    }
});


// ============================================================
// FETCH VEHICLE DETAILS
// ============================================================

async function fetch_vehicle_details(frm) {
    if (!frm.doc.vehicle_serial_no) {
        await frm.set_value("item", "");
        return;
    }

    try {
        const response = await frappe.call({
            method: "byky_app.vehicle_tear_down.get_vehicle_details",
            args: {
                serial_no: frm.doc.vehicle_serial_no
            }
        });

        const data = response.message || {};

        // Use the actual parent fieldname: "item".
        if (frm.fields_dict.item) {
            await frm.set_value("item", data.item || "");
        } else {
            console.error(
                "Vehicle Tear Down does not contain the parent field 'item'."
            );
        }

    } catch (error) {
        console.error("Vehicle details error:", error);

        frappe.msgprint({
            title: __("Vehicle Details Error"),
            indicator: "red",
            message: __(
                "Could not retrieve vehicle details. Check the Python method and Error Log."
            )
        });
    }
}


