// ============================================================
// DEFAULT DESTINATION WAREHOUSE (no hard-coded value)
// ============================================================

function get_default_destination(frm, row) {
    // Only use a warehouse already recorded for this item.
    const existing = (frm.doc.storage_location || []).find(
        storage => storage.item === row.item_code && storage.warehouse
    );

    return existing ? existing.warehouse : "";
}


// ============================================================
// FILL MISSING DESTINATION WAREHOUSES
// ============================================================

function fill_missing_destinations(frm) {
    if (frm.doc.docstatus !== 0) {
        return;
    }

    (frm.doc.recovered_parts || []).forEach(row => {
        if (is_reusable(row) && row.item_code && !row.destination_warehouse) {
            row.destination_warehouse = get_default_destination(frm, row);
        }
    });

    frm.refresh_field("recovered_parts");
}


// ============================================================
// SYNCHRONIZE REUSABLE PARTS TO storage_location
// ============================================================

function sync_reusable_parts(frm) {
    // Do not modify submitted or cancelled documents.
    if (frm.doc.docstatus !== 0) {
        return;
    }

    const reusable_rows = (frm.doc.recovered_parts || []).filter(
        row => is_reusable(row) && row.item_code
    );

    const storage_rows = frm.doc.storage_location || [];

    // Preserve location details for existing item occurrences.
    const existing_by_item = {};

    storage_rows.forEach(row => {
        if (!row.item) {
            return;
        }

        if (!existing_by_item[row.item]) {
            existing_by_item[row.item] = [];
        }

        existing_by_item[row.item].push({
            warehouse: row.warehouse || "",
            floor: row.floor || "",
            area: row.area || "",
            shelf: row.shelf || "",
            rack: row.rack || "",
            uom: row.uom || "",
            quantity: row.quantity || 1
        });
    });

    // Count each item so duplicate items are supported.
    const desired_counts = {};
    const current_counts = {};

    reusable_rows.forEach(row => {
        desired_counts[row.item_code] =
            (desired_counts[row.item_code] || 0) + 1;
    });

    storage_rows.forEach(row => {
        if (row.item) {
            current_counts[row.item] =
                (current_counts[row.item] || 0) + 1;
        }
    });

    const same_items =
        JSON.stringify(sort_object(desired_counts)) ===
        JSON.stringify(sort_object(current_counts));

    // --------------------------------------------------------
    // CASE 1: The item rows already match.
    // Update quantities and destination warehouses in place.
    // --------------------------------------------------------

    if (same_items) {
        const occurrence = {};

        reusable_rows.forEach(row => {
            const item_code = row.item_code;

            occurrence[item_code] = occurrence[item_code] || 0;

            const matching_rows = storage_rows.filter(
                storage => storage.item === item_code
            );

            const storage = matching_rows[occurrence[item_code]];

            occurrence[item_code] += 1;

            if (!storage) {
                return;
            }

            const quantity = row.quantity || 1;

            if (Number(storage.quantity || 0) !== Number(quantity)) {
                frappe.model.set_value(
                    storage.doctype,
                    storage.name,
                    "quantity",
                    quantity
                );
            }

            if (
                row.destination_warehouse &&
                storage.warehouse !== row.destination_warehouse
            ) {
                frappe.model.set_value(
                    storage.doctype,
                    storage.name,
                    "warehouse",
                    row.destination_warehouse
                );
            }
        });

        frm.refresh_field("storage_location");
        return;
    }

    // --------------------------------------------------------
    // CASE 2: Item rows changed.
    // Rebuild the table and preserve matching location details.
    // --------------------------------------------------------

    frm.clear_table("storage_location");

    const occurrence = {};

    reusable_rows.forEach(row => {
        const item_code = row.item_code;

        occurrence[item_code] = occurrence[item_code] || 0;

        const old_rows = existing_by_item[item_code] || [];
        const old = old_rows[occurrence[item_code]] || {};

        occurrence[item_code] += 1;

        const storage = frm.add_child("storage_location");

        storage.item = item_code;
        storage.quantity = row.quantity || 1;

        storage.warehouse =
            row.destination_warehouse ||
            old.warehouse ||
            "";

        storage.floor = old.floor || "";
        storage.area = old.area || "";
        storage.shelf = old.shelf || "";
        storage.rack = old.rack || "";
        storage.uom = old.uom || "";
    });

    frm.refresh_field("storage_location");
}


// ============================================================
// SORT OBJECT KEYS FOR CONSISTENT COMPARISON
// ============================================================

function sort_object(obj) {
    const result = {};

    Object.keys(obj)
        .sort()
        .forEach(key => {
            result[key] = obj[key];
        });

    return result;
}


