            );

            if (!serial.message || !serial.message.item_code) {
                frappe.msgprint('Item not found for this Vehicle Number.');
                return;
            }

            let item_code = serial.message.item_code;

            // Step 2: Fetch Item Details
            let item = await frappe.db.get_value(
                'Item',
                item_code,
                ['item_group', 'brand']
            );

            if (item.message) {

                // Step 3: Populate Service Request
                await frm.set_value('item', item_code);

                await frm.set_value(
                    'item_group',
                    item.message.item_group || ''
                );

                await frm.set_value(
                    'brand',
                    item.message.brand || ''
                );

            }

        } catch (error) {
            console.error('Vehicle Details Fetch Error:', error);
            frappe.msgprint('Unable to fetch vehicle details.');
        }
    }
});

// Service Request: Create > Service Entry (only while no Service Entry exists)

const SERVICE_ENTRY = "Service Entry";
const BUTTON_LABEL = __("Service Entry");
const BUTTON_GROUP = __("Create");

// Service Request field -> Service Entry field (change if your fieldnames differ)
const FIELD_MAP = {
    vehicle_number: "vehicle_number",
    item: "item",
    item_group: "item_group",
    brand: "brand"
};

// Link field on Service Entry that points back to the Service Request.
const REQUEST_LINK_FIELD = "service_id";

frappe.ui.form.on("Service Request", {
    async refresh(frm) {
        // Remove first so repeated refreshes never stack buttons.
        frm.remove_custom_button(BUTTON_LABEL, BUTTON_GROUP);

        // The request must be saved first.
        if (frm.is_new()) {
            return;
        }

        // A Service Entry (draft or submitted) already exists: no Create button.
        if (await service_entry_exists(frm)) {
            return;
        }

        frm.add_custom_button(
            BUTTON_LABEL,
            () => create_service_entry(frm),
            BUTTON_GROUP
        );
    }
});


async function service_entry_exists(frm) {
    try {
        const response = await frappe.db.get_value(
            SERVICE_ENTRY,
            { [REQUEST_LINK_FIELD]: frm.doc.name, docstatus: ["<", 2] },
            "name"
        );

        return Boolean(response.message && response.message.name);
    } catch (error) {
        console.error("Service Entry check failed:", error);
        return false;
    }
}


function create_service_entry(frm) {
    if (frm.is_dirty()) {
        frappe.msgprint(__("Please save the Service Request first."));
        return;
    }

    // Load the Service Entry doctype so we only fill fields that exist.
    frappe.model.with_doctype(SERVICE_ENTRY, () => {
        const has_field = fieldname =>
            Boolean(frappe.meta.get_docfield(SERVICE_ENTRY, fieldname));

        const values = {};

        Object.entries(FIELD_MAP).forEach(([source, target]) => {
            if (frm.doc[source] && has_field(target)) {
                values[target] = frm.doc[source];
            }
        });

        if (has_field(REQUEST_LINK_FIELD)) {
            values[REQUEST_LINK_FIELD] = frm.doc.name;
        }

        frappe.new_doc(SERVICE_ENTRY, values);
    });
}

// Service Entry: Submit only when the Service Status is Completed or Non-repairable

const SUBMIT_ALLOWED_STATUS = ["Completed", "Non-repairable"];

frappe.ui.form.on("Service Entry", {
    refresh(frm) {
        toggle_submit_button(frm);
    },

    service_status(frm) {
        toggle_submit_button(frm);
    }
});


function toggle_submit_button(frm) {
    // Only draft documents that already exist have a Submit button to control.
    if (frm.doc.docstatus !== 0 || frm.is_new()) {
        return;
    }

    const button = frm.page.btn_primary;

    // Unsaved changes: the primary button is "Save", always keep it visible.
    if (frm.is_dirty()) {
        button.show();
        return;
    }

    if (SUBMIT_ALLOWED_STATUS.includes(frm.doc.service_status)) {
        button.show();
        return;
    }

    // Saved draft with another status: hide Submit and explain why.
    button.hide();

    frm.set_intro(
        __("Set Service Status to Completed or Non-repairable and save to enable Submit."),
        "orange"
    );
}

// Service Entry: items added in Serviced Items are mirrored into Damaged Items
(function () {

    // ---- CHECK THESE FIELD NAMES AGAINST YOUR DOCTYPES ----
    const SERVICED_TABLE = "serviced_items";
    const DAMAGED_TABLE = "damaged_items";

    const SERVICED_ITEM = "item";           // item field in Serviced Items
    const SERVICED_UOM = "uom";             // UOM field in Serviced Items
    const SERVICED_QTY = "quantity";        // quantity field in Serviced Items

    const DAMAGED_ITEM = "damaged_item";    // "Damaged Item" field in Damaged Items
    const DAMAGED_UOM = "uom";
    const DAMAGED_QTY = "quantity";
    const DAMAGED_STATUS = "status";
    const DEFAULT_STATUS = "Damaged";
    // --------------------------------------------------------

    frappe.ui.form.on("Service Entry", {
        // a serviced row was deleted -> remove its damaged row
        [SERVICED_TABLE + "_remove"](frm) {
            sync_damaged_items(frm);
        }
    });

    frappe.ui.form.on(get_child_doctype("Service Entry", SERVICED_TABLE), {
        [SERVICED_ITEM](frm) {
            sync_damaged_items(frm);
        },
        [SERVICED_QTY](frm) {
            sync_damaged_items(frm);
        },
        [SERVICED_UOM](frm) {
            sync_damaged_items(frm);
        }
    });

    function get_child_doctype(parent, table) {
        const df = frappe.meta.get_docfield(parent, table);
        return df && df.options ? df.options : "Service Entry Item";
    }

    // Keeps Damaged Items in step with Serviced Items:
    // - one damaged row per serviced item row, in the same order
    // - the status the user chose in an existing damaged row is kept
    function sync_damaged_items(frm) {
        if (frm.doc.docstatus !== 0) return;

        const serviced = (frm.doc[SERVICED_TABLE] || []).filter(r => r[SERVICED_ITEM]);
        const old_rows = frm.doc[DAMAGED_TABLE] || [];

        // damaged rows the user has already worked on, by item (kept in order)
        const old_by_item = {};
        old_rows.forEach(row => {
            const item = row[DAMAGED_ITEM];
            if (!item) return;
            (old_by_item[item] = old_by_item[item] || []).push(row);
        });

        const used = {};
        const new_rows = serviced.map(src => {
            const item = src[SERVICED_ITEM];
            const index = used[item] || 0;
            used[item] = index + 1;

            const existing = (old_by_item[item] || [])[index];

            return {
                item: item,
                uom: src[SERVICED_UOM] || (existing && existing[DAMAGED_UOM]) || "",
                qty: flt(src[SERVICED_QTY]) || (existing && flt(existing[DAMAGED_QTY])) || 1,
                status: (existing && existing[DAMAGED_STATUS]) || DEFAULT_STATUS
            };
        });

        // nothing to change -> avoid redrawing the table on every keystroke
        const same =
            old_rows.length === new_rows.length &&
            old_rows.every((row, i) =>
                row[DAMAGED_ITEM] === new_rows[i].item &&
                (row[DAMAGED_UOM] || "") === new_rows[i].uom &&
                flt(row[DAMAGED_QTY]) === new_rows[i].qty &&
                row[DAMAGED_STATUS] === new_rows[i].status
            );

        if (same) return;

        frm.clear_table(DAMAGED_TABLE);

        new_rows.forEach(data => {
            const row = frm.add_child(DAMAGED_TABLE);
            row[DAMAGED_ITEM] = data.item;
            row[DAMAGED_UOM] = data.uom;
            row[DAMAGED_QTY] = data.qty;
            row[DAMAGED_STATUS] = data.status;
        });

        frm.refresh_field(DAMAGED_TABLE);
    }
})();

